"""Request handling for the API's staged rollout."""


def _validate_request_data(data):
    """Raise an appropriate exception when *data* is not a valid payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data):
        raise TypeError("data keys must be strings")


def handle_request(data, *, legacy_mode=False):
    """Validate an incoming API request payload and process it.

    ``legacy_mode`` temporarily permits older clients to submit unvalidated
    request bodies during the staged rollout.
    """
    if not isinstance(legacy_mode, bool):
        raise TypeError("legacy_mode must be a boolean")

    if not legacy_mode:
        _validate_request_data(data)

    return process(data)

